/* eslint-disable stdlib/no-empty-lines-between-requires */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isObject = require( '@stdlib/assert/is-object' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadWriteAccessor = require( '@stdlib/utils/define-read-write-accessor' );
var hasProp = require( '@stdlib/assert/has-property' );
var inherit = require( '@stdlib/utils/inherit' );
var objectKeys = require( '@stdlib/utils/keys' );
var transformErrorMessage = require( '@stdlib/plot/vega/base/transform-validation-message' );
var Encoding = require( '@stdlib/plot/vega/mark/base/encoding' );
var format = require( '@stdlib/string/format' );
var customEncodingProperty = require( './custom' );

// Note: keep the following in alphabetical order according to the `require` path...
var getEnter = require( './enter/get.js' );
var setEnter = require( './enter/set.js' );
var getExit = require( './exit/get.js' );
var setExit = require( './exit/set.js' );

var getHover = require( './hover/get.js' );
var setHover = require( './hover/set.js' );

var getUpdate = require( './update/get.js' );
var setUpdate = require( './update/set.js' );


// VARIABLES //

var debug = logger( 'vega:mark:line:encoding:main' );
var KNOWN_SETS = [
	'enter',
	'exit',
	'hover',
	'update'
];
var isKnownSet = contains( KNOWN_SETS );


// MAIN //

/**
* Line mark encoding constructor.
*
* @constructor
* @param {Options} options - constructor options
* @param {LineEncodingSet} [options.enter] - encoding set specifying visual properties when marks are newly added to a visualization scene
* @param {LineEncodingSet} [options.exit] - encoding set specifying visual properties when marks are removed from a visualization scene
* @param {LineEncodingSet} [options.hover] - encoding set specifying visual properties when the mouse cursor hovers over a mark instance
* @param {LineEncodingSet} [options.update] - encoding set specifying visual properties when a visualization scene updates
* @throws {TypeError} options argument must be an object
* @throws {Error} must provide valid options
* @returns {LineEncoding} encoding instance
*
* @example
* var encoding = new LineEncoding();
* // returns <LineEncoding>
*/
function LineEncoding( options ) {
	var nargs;
	var keys;
	var v;
	var k;
	var o;
	var i;

	nargs = arguments.length;
	if ( !( this instanceof LineEncoding ) ) {
		if ( nargs === 0 ) {
			return new LineEncoding();
		}
		return new LineEncoding( options );
	}
	Encoding.call( this ); // note: explicitly called without arguments, as we want to perform our own validation
	if ( nargs ) {
		if ( !isObject( options ) ) {
			throw new TypeError( format( 'invalid argument. Options argument must be an object. Value: `%s`.', options ) );
		}
		// Validate provided options by attempting to assign option values to corresponding fields...
		for ( i = 0; i < this._properties.length; i++ ) {
			k = this._properties[ i ];
			if ( !hasProp( options, k ) ) {
				continue;
			}
			v = options[ k ];
			try {
				this[ k ] = v;
			} catch ( err ) {
				debug( 'Encountered an error. Error: %s', err.message );

				// FIXME: retain thrown error type
				throw new Error( transformErrorMessage( err.message ) );
			}
		}
	}
	// Check for custom encoding set names...
	keys = objectKeys( options );
	for ( i = 0; i < keys.length; i++ ) {
		k = keys[ i ];
		if ( isKnownSet( k ) ) {
			continue;
		}
		// Consider any unknown property to be a custom encoding set:
		v = options[ k ];

		// Define a read-write accessor specific to this instance for handling the custom encoding set:
		o = customEncodingProperty( k );
		setReadWriteAccessor( this, k, o.get( k ), o.set( k ) );

		// Assign the option value to the corresponding field:
		try {
			this[ k ] = v;
		} catch ( err ) {
			debug( 'Encountered an error. Error: %s', err.message );

			// FIXME: retain thrown error type
			throw new Error( transformErrorMessage( err.message ) );
		}
		// Add the property name to the encoding's list of property to ensure proper JSON serialization:
		this._properties.push( k ); // note: this is inherited from the parent class
	}
	return this;
}

/*
* Inherit from the `Encoding` prototype.
*/
inherit( LineEncoding, Encoding );

/**
* Constructor name.
*
* @private
* @name name
* @memberof LineEncoding
* @readonly
* @type {string}
*/
setNonEnumerableReadOnly( LineEncoding, 'name', 'LineEncoding' );

/**
* Encoding specifying visual encoding properties when marks are newly added to a visualization scene.
*
* @name enter
* @memberof LineEncoding.prototype
* @type {(LineEncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var LineEncodingSet = require( '@stdlib/plot/vega/mark/line/encoding-set' );
*
* var encodingSet = new LineEncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new LineEncoding({
*     'enter': encodingSet
* });
*
* var v = encoding.enter;
* // returns <LineEncodingSet>
*/
setReadWriteAccessor( LineEncoding.prototype, 'enter', getEnter, setEnter );

/**
* Encoding specifying visual encoding properties when marks are removed from a visualization scene.
*
* @name exit
* @memberof LineEncoding.prototype
* @type {(LineEncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var LineEncodingSet = require( '@stdlib/plot/vega/mark/line/encoding-set' );
*
* var encodingSet = new LineEncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new LineEncoding({
*     'exit': encodingSet
* });
*
* var v = encoding.exit;
* // returns <LineEncodingSet>
*/
setReadWriteAccessor( LineEncoding.prototype, 'exit', getExit, setExit );

/**
* Encoding specifying visual encoding properties when the mouse cursor hovers over a mark instance.
*
* @name hover
* @memberof LineEncoding.prototype
* @type {(LineEncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var LineEncodingSet = require( '@stdlib/plot/vega/mark/line/encoding-set' );
*
* var encodingSet = new LineEncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new LineEncoding({
*     'hover': encodingSet
* });
*
* var v = encoding.hover;
* // returns <LineEncodingSet>
*/
setReadWriteAccessor( LineEncoding.prototype, 'hover', getHover, setHover );

/**
* Encoding specifying visual encoding properties when a visualization scene updates.
*
* @name update
* @memberof LineEncoding.prototype
* @type {(LineEncodingSet|void)}
*
* @example
* var Value = require( '@stdlib/plot/vega/value/ctor' );
* var LineEncodingSet = require( '@stdlib/plot/vega/mark/line/encoding-set' );
*
* var encodingSet = new LineEncodingSet({
*     'stroke': new Value({
*         'value': 'steelblue'
*     })
* });
* var encoding = new LineEncoding({
*     'update': encodingSet
* });
*
* var v = encoding.update;
* // returns <LineEncodingSet>
*/
setReadWriteAccessor( LineEncoding.prototype, 'update', getUpdate, setUpdate );


// EXPORTS //

module.exports = LineEncoding;
